  ('m ⊗ n = m² + n² işlemi tanımlanıyor. x ⊗ 4 = 41 ve x pozitif ise x kaçtır?', '5', ['3', '6', '50'], 'x² + 16 = 41 ⇒ x = 5.'),
  ('a △ b = 3a − 2b işlemi için x △ 4 = 13 eşitliğini sağlayan x değeri kaçtır?', '7', ['5', '9', '11'], '3x − 8 = 13 ⇒ x = 7.'),
  ('Bir makine girdiyi önce 4 artırıp sonucu 2 ile çarpıyor, ardından 6 çıkarıyor. Makine çıktı olarak 20 verdiğine göre girdi kaçtır?', '9', ['10', '8', '13'], '2(x + 4) − 6 = 20 ⇒ x + 4 = 13 ⇒ x = 9.'),
  ('Bir makineye girilen her sayı önce karesi alınıp sonra 1 eksiltiliyor. Makineye sırayla 3 ve ardından bu çıktı girilirse son çıktı kaç olur?', '63', ['80', '630', '48'], 'Girdi 3 için çıktı 3² − 1 = 8; 8 girilince 8² − 1 = 63 olur.'),
  ('Bir makine girdiyi önce 2 ile çarpıp sonra 3 ekliyor. Makineden iki kez geçirilen bir sayı 29 oluyorsa, ilk girilen sayı kaçtır?', '5', ['6', '4', '13'], 'İki geçişte 2(2x + 3) + 3 = 4x + 9 = 29 ⇒ x = 5.'),
  ('Bir makine girilen iki basamaklı sayının rakamlarının yerini değiştirip elde edilen sayıyı 9 ile çarpıyor. Makineye 27 girildiğinde çıktı kaçtır?', '648', ['6480', '594', '72'], '27 → 72; 72·9 = 648.'),
  ('a ⊕ b = ekok(a, b) − ebob(a, b) tanımlanıyor. 12 ⊕ 18 işleminin sonucu kaçtır?', '30', ['36', '300', '42'], 'EKOK(12,18) = 36, EBOB = 6; 36 − 6 = 30.'),
  ('Bir oyunda x # y simgesi, x ile y arasındaki mutlak farkın bir fazlasını gösteriyor. Buna göre (2 # 9) # (7 # 3) ifadesi kaça eşittir?', '4', ['2', '5', '40'], '2 # 9 = 8, 7 # 3 = 5, 8 # 5 = 4.'),
  ('p ▲ q işlemi, p ile q\'nun büyüğünden küçüğünü çıkarıp çıkan sayıyı 2 ile çarpıyor. (3 ▲ 10) ▲ (6 ▲ 4) işleminin sonucu kaçtır?', '20', ['200', '14', '4'], '3 ▲ 10 = 14, 6 ▲ 4 = 4, 14 ▲ 4 = 20.'),
  ('m ⊛ n = m·n + 1 işlemi için 2 ⊛ (3 ⊛ (4 ⊛ 1)) sonucu kaçtır?', '33', ['31', '27', '330'], '4 ⊛ 1 = 5; 3 ⊛ 5 = 16; 2 ⊛ 16 = 33.'),
  ('Bir okuldaki 100 öğrencinin 60\'ı futbol, 45\'i basketbol oynamaktadır ve 20 öğrenci her iki sporu da yapmaktadır. Hiçbir sporu yapmayan kaç öğrenci vardır?', '15', ['10', '20', '150'], 'En az bir spor yapanlar 60 + 45 − 20 = 85; 100 − 85 = 15.'),
  ('Bir ankette 80 kişiye çay ve kahve içip içmedikleri sorulmuş; 52 kişi çay, 38 kişi kahve içtiğini, 14 kişi ise ikisini de içmediğini söylemiştir. Hem çay hem kahve içenlerin sayısı kaçtır?', '24', ['240', '28', '38'], 'En az birini içen 80 − 14 = 66 kişi vardır; kesişim 52 + 38 − 66 = 24.'),
  ('Bir sınıfta gözlüklü kız 7, gözlüksüz kız 11, gözlüklü erkek 5 ve gözlüksüz erkek 9 kişidir. Sınıfta gözlük kullanan öğrencilerin oranı yüzde kaçtır?', '37,5', ['30', '40', '42,5'], 'Toplam 32, gözlüklü 12 öğrenci vardır; 12/32 = %37,5.'),
  ('Üç mahallede (X, Y, Z) boş bina sayıları 14, 22 ve 9, toplam bina sayıları ise 70, 88 ve 30\'dur. Boş bina oranı en yüksek olan mahalle hangisidir?', 'Z', ['X', 'Y', 'Üçünde de oran eşittir'], 'Oranlar: X 14/70 = 0,20; Y 22/88 = 0,25; Z 9/30 = 0,30. En yüksek Z\'dir.'),
  ('Bir haftanın günlük yağış miktarları (mm) sırasıyla pazartesi 4, salı 0, çarşamba 7, perşembe 12, cuma 5, cumartesi 0, pazar 2\'dir. Yalnızca yağış olan günler dikkate alınırsa günlük ortalama yağış kaç mm\'dir?', '6', ['4', '5', '30'], 'Yağışlı beş günün toplamı 30 mm; 30/5 = 6.'),
  ('Bir öğrenci ilk üç sınavdan 70, 85 ve 90 almıştır. Dört sınavın ortalamasının 82,5 olması için dördüncü sınavdan kaç alması gerekir?', '85', ['850', '82', '90'], 'Toplam 4·82,5 = 330; 330 − 245 = 85.'),
  ('Bir okul kütüphanesinde ödünç alınan kitap sayısı ocakta 120, şubatta 95, martta 140\'tır. Dört aylık ortalamanın 120 olması için nisanda kaç kitap ödünç alınmalıdır?', '125', ['1250', '120', '135'], 'Toplam 480; 480 − 355 = 125.'),
  ('Bir öğrencinin matematik notları 80, 90, 90, 70 ve 85\'tir. Notların medyanı ile aritmetik ortalaması arasındaki fark kaçtır?', '2', ['0', '20', '5'], 'Sıralı notlar 70, 80, 85, 90, 90: medyan 85; ortalama 415/5 = 83; fark 2.'),
  ('Fiyatları 120, 85, 60, 150 ve 45 lira olan beş ürün vardır. 300 lirası olan bir kişi, her üründen en fazla birer tane alarak en çok kaç farklı ürün satın alabilir?', '3', ['2', '4', '30'], 'En ucuz üçü 45 + 60 + 85 = 190; dördüncü ürünle 310 olur ve 300\'ü aşar.'),
  ('Bir okulda dersler 09.00\'da başlıyor; her ders 40 dakika, derslerin arasındaki teneffüs 10 dakikadır. Beşinci ders saat kaçta biter?', '13.00', ['12.40', '13.10', '12.50'], '5·40 + 4·10 = 240 dakika; 09.00 + 4 saat = 13.00.'),
  ('Bir sinemada seanslar 13.30\'dan başlayarak 2 saat 30 dakika arayla yapılıyor ve film 2 saat 15 dakika sürüyor. Dördüncü seansın film bitiş saati kaçtır?', '23.15', ['21.00', '22.45', '23.30'], 'Dördüncü seans 13.30 + 7,5 saat = 21.00\'de başlar; 2 saat 15 dakika sonra 23.15\'te biter.'),
  ('Aşağıdaki bileşik önermelerden hangisi her zaman doğrudur (totolojidir)?', 'p ∨ ¬p', ['p ∧ ¬p', 'p → ¬p', 'p ↔ ¬p'], 'Bir önerme ya doğrudur ya yanlıştır; p ∨ ¬p her satırda doğrudur.'),
  ('Aşağıdaki bileşik önermelerden hangisi her zaman yanlıştır (çelişkidir)?', 'p ∧ ¬p', ['p ∨ ¬p', 'p → p', 'p ↔ p'], 'Bir önerme aynı anda hem doğru hem yanlış olamaz.'),
  ('Dört öğretmen (Nur, Okan, Pınar, Rıza) matematik, fizik, kimya ve biyoloji derslerini birer tane okutmaktadır. Nur matematik, fizik ve kimya okutmaz. Okan matematik, kimya ve biyoloji okutmaz. Pınar fizik ve matematik okutmaz. Rıza kimya ve biyoloji okutmaz. Rıza hangi dersi okutur?', 'matematik dersini okutur', ['fizik dersini okutur', 'kimya dersini okutur', 'biyoloji dersini okutur'], 'Nur biyoloji, Okan fizik okutur; Pınar kimya, Rıza matematik okutur.'),
  ('Bir terazide 2 elma, 3 armuda; 1 armut ise 4 kirazın ağırlığına eşittir. Buna göre 1 elma kaç kirazın ağırlığına eşittir?', '6', ['5', '8', '12'], '1 armut = 4 kiraz ⇒ 3 armut = 12 kiraz = 2 elma ⇒ 1 elma = 6 kiraz.'),
  ('Üç çuval ikişerli tartılıyor: A+B = 50 kg, B+C = 60 kg, A+C = 70 kg. En ağır çuval kaç kg\'dır?', '40', ['30', '400', '25'], 'Toplam 90 kg; A = 30, B = 20, C = 40. En ağır C = 40.'),
  ('Bir saat doğru kurulmuş ve her saatte 4 dakika ileri gitmektedir. Saat sabah 08.00\'de doğru zamanı gösterirken, gerçek saat 14.00 olduğunda bu saat kaçı gösterir?', '14.24', ['14.04', '14.20', '14.30'], 'Altı saatte 6·4 = 24 dakika ileri gider: 14.24.'),
  ('Aynadaki görüntüsü 03.25 olarak görünen bir kol saatinin gerçek zamanı kaçtır?', '08.35', ['03.35', '09.25', '08.25'], 'Aynadaki saat 12.00\'den çıkarılarak bulunur: 12.00 − 03.25 = 08.35.'),
  ('Bir kuyunun derinliği 10 metredir. Kuyunun dibindeki bir salyangoz her gün 3 metre tırmanıp her gece 2 metre aşağı kayıyor. Salyangoz kaçıncı günün gündüzünde kuyunun ağzına ulaşır?', '8', ['7', '9', '10'], 'Her tam günde net 1 m çıkar; 7. günün sonunda 7 m\'dedir, 8. gün gündüz 3 m daha çıkarak 10 m\'ye ulaşır.'),
  ('Bir kurbağa 12 metre derinliğindeki bir kuyudan çıkmak istiyor; gündüz 4 metre sıçrıyor, gece 3 metre kayıyor. Kaçıncı günde kuyudan çıkar?', '9', ['8', '10', '12'], 'Her gün net 1 metre çıkar; 8. gün sonunda 8 m\'dedir, 9. gün gündüz 4 m çıkarak 12 m\'ye ulaşır.'),
  ('Altı arkadaş yuvarlak bir masanın etrafına, yalnızca oturma düzeninin göreli konumu önemli olacak biçimde (döndürülerek elde edilenler aynı sayılır) kaç farklı biçimde oturabilir?', '120', ['720', '1200', '24'], 'Dairesel permütasyon: (6 − 1)! = 120.'),
  ('Üç kutunun üzerinde ‘Elma’, ‘Portakal’ ve ‘Elma-Portakal’ etiketleri vardır ve üç etiketin hepsi yanlıştır. İçinde yalnız elma ya da yalnız portakal ya da karışık meyve bulunan kutulardan, ‘Elma-Portakal’ etiketli kutudan bir meyve çekilirse ve bu meyve elma çıkarsa bu kutuda ne vardır?', 'Sadece elmalar vardır.', ['Sadece portakallar vardır.', 'Elma ve portakal karışıktır.', 'Belirlenemez.'], 'Etiket yanlış olduğundan kutu karışık olamaz; elma çıktığına göre kutuda yalnız elma vardır.'),
  ('1\'den 50\'ye kadar (50 dâhil) bütün doğal sayılar yan yana yazıldığında 5 rakamı kaç kez kullanılır?', '6', ['5', '10', '15'], 'Birler basamağında 5, 15, 25, 35, 45 (5 kez); onlar basamağında yalnız 50 (1 kez). Toplam 6.'),
  ('Bir kitabın 250 sayfası vardır ve sayfa numaraları 1\'den başlayarak yazılmıştır. Numaralandırmada toplam kaç rakam kullanılmıştır?', '642', ['6420', '651', '550'], '1–9: 9 rakam; 10–99: 180 rakam; 100–250: 151·3 = 453 rakam; toplam 642.'),
  ('Üç basamaklı kaç doğal sayı, soldan okunuşu ile sağdan okunuşu aynı olan (palindrom) bir sayıdır?', '90', ['81', '100', '45'], 'Yüzler basamağı 9 seçenek, onlar basamağı 10 seçenek; birler basamağı yüzler basamağına eşittir: 9·10 = 90.'),
  ('50 ile 200 arasında (50 ve 200 dâhil) kaç tane tam kare sayı vardır?', '7', ['6', '8', '70'], 'Tam kareler 64, 81, 100, 121, 144, 169, 196: 7 tane.'),
  ('1\'den 99\'a kadar olan doğal sayıların rakamları toplamı kaçtır?', '900', ['9000', '855', '891'], 'Birler ve onlar basamaklarının her biri 0–9 rakamlarını 10\'ar kez alır: 2·45·10 = 900.'),
  ('11 · 11 = 121, 111 · 111 = 12321, 1111 · 1111 = 1234321 örüntüsüne göre 11111 · 11111 sayısının rakamları toplamı kaçtır?', '25', ['36', '250', '41'], '11111² = 123454321; rakamları toplamı 1+2+3+4+5+4+3+2+1 = 25.'),
  ('9·9 + 7 = 88, 98·9 + 6 = 888, 987·9 + 5 = 8888 örüntüsü sürdürülürse 98765·9 + 3 işleminin sonucu kaç olur?', '888888', ['88888', '8888888', '888889'], 'Örüntüye göre sonuç, çarpılan sayının rakam sayısı kadar 8\'den oluşur; doğrudan hesap: 98765·9 = 888885, 3 eklenince 888888 bulunur.'),
  ('12345679 sayısı 9 ile çarpılınca 111111111 elde edilir. Aynı sayı 27 ile çarpılırsa sonuç kaç olur?', '333333333', ['333333330', '333333334', '3333333333'], '27 = 9·3 olduğundan sonuç 111111111·3 = 333333333.'),
  ('Her biri bir önceki sayının rakamlarının toplamı kadar artırılarak elde edilen şu dizide ilk terim 8\'dir: 8, 16, 23, … Dördüncü terim kaçtır?', '28', ['280', '33', '34'], 'Terimler: 8, 8 + 8 = 16, 16 + 7 = 23, 23 + 5 = 28.'),
  ('3 basamaklı bir sayının yüzler basamağı onlar basamağının 2 katı, onlar basamağı birler basamağının 2 katıdır ve rakamlar toplamı 14\'tür. Bu sayı kaçtır?', '842', ['8420', '482', '248'], 'Rakamlar 4k, 2k, k biçimindedir; 7k = 14 ⇒ k = 2: 842.'),
  ('3, 10, 17, 24, … dizisinde 157 sayısı kaçıncı terimdir?', '23', ['22', '24', '230'], 'Genel terim 7n − 4\'tür. Terim 157 için sıra numarası 23 bulunur.'),
  ('Bir otobüs hattında yolcu sayıları 11, 17, 23, 29, … biçiminde artıyor. 245 yolculu sefer kaçıncı seferdir?', '40', ['400', '41', '42'], 'Genel terim 6n + 5\'tir. Terim 245 için sıra numarası 40 bulunur.'),
  ('4, 7, 12, 19, … dizisinin genel terimi n² + 3\'tür. Kaçıncı terim 147\'dir?', '12', ['11', '120', '14'], 'Genel terim n² + 3\'tür. Terim 147 için sıra numarası 12 bulunur.'),
  ('Bir merdivenin basamak yükseklikleri (cm) 2, 8, 18, 32, … şeklinde ilerlemektedir. 450 cm kaçıncı basamaktır?', '15', ['14', '16', '150'], 'Genel terim 2n²\'dir. Terim 450 için sıra numarası 15 bulunur.'),
  ('Bir yurtta oda numaraları 14, 17, 20, 23, … biçiminde ilerliyor. 101 numaralı oda kaçıncıdır?', '30', ['29', '31', '300'], 'Genel terim 3n + 11\'dir. Terim 101 için sıra numarası 30 bulunur.'),
  ('Bir öğrenci sınav hazırlığında soru sayılarını 6, 11, 16, 21, … biçiminde artırıyor. İlk 12 gündeki toplam soru sayısı kaçtır?', '402', ['4020', '341', '414'], 'Genel terim 5n + 1\'dir. İlk 12 terimin toplamı 402 olur.'),
  ('Bir kumbarada ilk gün 3 lira, sonraki günlerde sırasıyla 7, 11, 15, … lira biriktiriliyor (3, 7, 11, 15 ...). 15 günün sonunda toplam kaç lira birikir?', '465', ['528', '4650', '480'], 'Genel terim 4n − 1\'dir. İlk 15 terimin toplamı 465 olur.'),
  ('Bir mağaza ilk ay 2, sonraki aylarda sırasıyla 6, 18, 54, … (2, 6, 18, 54 …) adet ürün satıyor. İlk sekiz ayda satılan toplam ürün sayısı kaçtır?', '6560', ['19682', '2186', '6568'], 'Geometrik dizidir, r = 3. İlk 8 terimin toplamı 6560 olur.'),
  ('Bir nakışçı her işlemeye, sıra numarasının karesi kadar boncuk dikiyor: 1, 4, 9, 16, … İlk on işlemede toplam kaç boncuk kullanılmıştır?', '385', ['506', '285', '3850'], 'Terimler n²\'dir. İlk 10 terimin toplamı 385 olur.'),
  ('Bir kütüphanede raflara 1, 4, 7, 10, … biçiminde numara veriliyor; numaralar 3n − 2 kuralına uyuyor. Hangi numaralı bir raf bulunmaz?', '41', ['19', '34', '70'], 'Terimlerin 3\'e bölümünden kalan 1\'dir; 41 ≡ 2 (mod 3) olduğundan terim değildir.'),
  ('Bir bilgisayar oyununda seviye puanları n² + 1 kuralıyla hesaplanıyor (2, 5, 10, …). Hangi puan hiçbir seviyede alınamaz?', '64', ['26', '50', '82'], 'n² + 1 = 64 ⇒ n² = 63 olduğundan 64 terim değildir.'),
  ('Bir sayı oyununda kartlara tam karelerin bir fazlası yazılmıştır: 2, 5, 10, 17, … Aşağıdaki sayılardan hangisi bu kartlardan birinde yazılı olamaz?', '120', ['37', '101', '145'], 'n² + 1 = 120 ⇒ n² = 119 tam kare olmadığından 120 terim değildir.'),
  ('Ardışık iki doğal sayının çarpımı olarak 2, 6, 12, 20, … biçiminde yazılan sayılar arasında hangisi yer almaz?', '92', ['42', '72', '110'], '92 sayısı iki ardışık sayının çarpımı olmadığından terim değildir (9·10 = 90, 10·11 = 110).'),
  ('Her terimi önceki iki terimin toplamı olan 1, 1, 2, 3, 5, 8, … (Fibonacci) dizisi yazılırsa aşağıdaki sayılardan hangisi dizide yer almaz?', '100', ['34', '89', '233'], 'Fibonacci sayıları ... 55, 89, 144 şeklinde ilerler; 100 bu dizide yoktur.'),
  ('Pascal üçgeninde en üstteki satır 1\'dir; her sayı, hemen üstündeki iki sayının toplamıdır ve satır başları ile sonları 1\'dir. Bu üçgenin 10. satırındaki (üstteki 1 birinci satır sayılırsa) sayıların toplamı kaçtır?', '512', ['511', '1024', '100'], 'n. satırın toplamı 2^(n−1) olduğundan 10. satır toplamı 2⁹ = 512.'),
  ('Pascal üçgeninde (üstteki 1 sıfırıncı satır) 8. satırın baştan 4. sayısı kaçtır? Satırlar 1, 8, 28, … biçiminde başlamaktadır.', '56', ['28', '560', '64'], 'Sayı C(8,3) = 56.'),
  ('Doğal sayılar 1\'den başlayarak üçgen biçiminde dizilmiştir: 1. satırda 1, 2. satırda 2 ve 3, 3. satırda 4, 5 ve 6, … Bu diziliş 12. satıra kadar sürerse 12. satırın ilk sayısı kaçtır?', '67', ['670', '78', '79'], '12. satırdan önce 1+2+…+11 = 66 sayı vardır; 12. satır 67 ile başlar.'),
  ('Doğal sayılar 1\'den başlayarak üçgen biçimde dizilmiştir: 1. satırda 1, 2. satırda 2, 3, 3. satırda 4, 5, 6, … Bu düzenin 10. satırındaki sayıların toplamı kaçtır?', '505', ['450', '5050', '510'], '10. satır 46\'dan 55\'e kadardır: 10·(46+55)/2 = 505.'),
  ('Her satırında bir önceki satırdan 2 fazla sayı bulunan bir üçgenin 1. satırında 1 sayı, 2. satırında 3 sayı, 3. satırında 5 sayı vardır. Bu üçgenin ilk 12 satırında toplam kaç sayı bulunur?', '144', ['1440', '156', '121'], 'Satırlardaki sayılar tek sayılardır; ilk 12 tek sayının toplamı 12² = 144.'),
  ('Bir manav şunları söylüyor: 3 elma ile 2 armut 19 lira, 2 elma ile 3 armut 16 lira ediyor. 1 elma ile 1 armut birlikte kaç liradır?', '7', ['6', '70', '5'], 'İki denklem taraf tarafa toplanınca 5(E + A) = 35 ⇒ E + A = 7.'),
  ('Bir bulmacada 2 kare ve 1 daire birlikte 11, 1 kare ve 2 daire birlikte 10 olarak veriliyor. Bir karenin değeri kaçtır?', '4', ['3', '2', '40'], '2k + d = 11, k + 2d = 10 ⇒ k = 4, d = 3.'),
  ('Bir sınıfta 3 kalem ve 1 silgi toplam 13 lira, 1 kalem ve 2 silgi toplam 11 liradır. 5 kalem ve 5 silgi kaç liradır?', '35', ['350', '40', '45'], '3k + s = 13, k + 2s = 11 ⇒ k = 3, s = 4 değil; k = 3, s = 4: 3·3 + 4 = 13; 3 + 8 = 11 ✓. 5(3+4) = 35.'),
  ('Bir hayvanat bahçesinde fil, zürafa ve maymun için bilet fiyatları şöyle verilmiştir: 1 fil + 1 zürafa = 30 lira, 1 zürafa + 1 maymun = 22 lira, 1 fil + 1 maymun = 24 lira. Üçünü birden görmenin bilet fiyatı kaç liradır?', '38', ['76', '380', '40'], 'Üç denklemi toplayınca 2(F + Z + M) = 76 ⇒ F + Z + M = 38.'),
  ('Bir sınıfta üç öğrencinin boyları şöyledir: Ali ile Bora\'nın boyları toplamı 330 cm, Bora ile Can\'ın boyları toplamı 335 cm, Ali ile Can\'ın boyları toplamı 325 cm. Bora\'nın boyu kaç cm\'dir?', '170', ['1700', '160', '175'], 'Üçünün toplamı (330 + 335 + 325)/2 = 495; Bora = 495 − 325 = 170.'),
  ('a + b = 12, b + c = 15 ve a + c = 13 olduğuna göre a, b ve c sayılarının en büyüğü kaçtır?', '8', ['5', '80', '9'], 'Üç denklemin toplamı 2(a+b+c) = 40 ⇒ a+b+c = 20; c = 20 − 12 = 8, a = 5, b = 7.'),
  ('İngiliz alfabesinde A, B, E, J, … dizisinde ardışık harflerin sıra numaraları arasındaki fark 1, 3, 5, … biçiminde artmaktadır. Bir sonraki harf hangisidir?', 'Q', ['P', 'R', 'O'], 'Sıra numaraları 1, 2, 5, 10, 17 ⇒ 17. harf Q\'dur.'),
  ('A1, C4, E9, G16, … dizisinde harfler ikişer ilerlemekte, sayılar tam karelerdir. Beşinci terim hangisidir? (İngiliz alfabesi)', 'I25', ['I20', 'J25', 'H25'], 'Beşinci harf I; sayı 5² = 25.'),
  ('O, T, T, F, F, S, S, … dizisi, İngilizce sayıların (One, Two, Three, …) baş harflerinden oluşmaktadır. Sıradaki harf hangisidir?', 'E', ['N', 'T', 'S'], 'Sayılar: One, Two, Three, Four, Five, Six, Seven, Eight; sekizinci sayının baş harfi E\'dir.'),
  ('J, F, M, A, M, J, J, A, … dizisi bir yılın aylarının İngilizce adlarının baş harflerinden oluşmaktadır (January, February, …). Dizide sonraki harf hangisidir?', 'S', ['O', 'N', 'D'], 'Sekizinci aydan (August) sonra dokuzuncu ay September gelir.'),
  ('Y, V, S, P, … dizisinde (İngiliz alfabesi) harfler arasında 2\'şer harf atlanarak geriye doğru gidilmektedir. Sonraki harf hangisidir?', 'M', ['N', 'L', 'O'], 'Y(25), V(22), S(19), P(16) → M(13).'),
  ('A, Z, C, X, E, V, … biçiminde ilerleyen bir harf dizisinde tek sıradaki harfler ileriye, çift sıradaki harfler geriye doğru ikişer harf atlayarak ilerlemektedir (İngiliz alfabesi). Yedinci harf hangisidir?', 'G', ['F', 'H', 'T'], 'Tek sıralar: A, C, E, G; çift sıralar: Z, X, V, T.'),
  ('Altı vagonlu bir trende vagonlar baştan sona 1\'den 6\'ya numaralıdır ve her vagonda farklı bir yolcu grubu vardır: öğrenciler, turistler, işçiler, askerler, sporcular, doktorlar. Öğrenciler en baştadır; turistler işçilerin hemen önündedir; askerler turistlerin önünde ama öğrencilerin arkasındadır; sporcular işçilerden sonra, doktorlar en sondadır. İşçiler kaçıncı vagondadır?', '4', ['1', '2', '40'], 'Sıra: öğrenciler, askerler, turistler, işçiler, sporcular, doktorlar. İşçiler 4. vagondadır.'),
  ('Dört kız kardeş Aylin, Banu, Ceren ve Derya\'nın boyları farklıdır. Aylin, Banu\'dan uzundur. Ceren, Derya\'dan kısa fakat Banu\'dan uzundur. Banu, uzundan kısaya doğru yapılan sıralamada kaçıncı sıradadır?', '4', ['40', '2', '3'], 'Derya > Ceren > Banu ve Aylin > Banu olduğundan Banu en kısadır: dördüncü.'),
  ('Beş takımlı bir ligin puan sıralamasında Aslan, Kartal, Bozkurt, Şahin ve Doğan yer almaktadır. Aslan, Kartal\'ın hemen önündedir. Bozkurt son sırada değildir ve Şahin\'den geridedir. Doğan ikinci sıradadır. Aslan kaçıncı sıradadır?', '4', ['1', '2', '3'], 'Şahin birinci, Doğan ikinci, Bozkurt üçüncü, Aslan dördüncü, Kartal beşincidir.'),
  ('Beş katlı bir apartmanın her katında bir kişi oturmaktadır: Rıza en alt kattadır. Okan, Nil\'in hemen altındadır. Seda, Nil\'in iki kat altındadır. Pelin, Nil\'den daha yüksek bir kattadır. Okan kaçıncı kattadır (en alt kat 1)?', '3', ['1', '30', '4'], 'Rıza 1, Seda 2, Okan 3, Nil 4, Pelin 5. kattadır.'),
  ('Beş öğrenci sözlüye şu koşullarla kalkacaktır: Can, Ali\'den önce; Ali, Berk\'ten önce; Deniz, Berk\'ten hemen sonra; Ece ise Can\'dan hemen sonra gidecektir. Berk kaçıncı sırada sözlüye kalkar?', '4', ['1', '2', '40'], 'Sıra Can, Ece, Ali, Berk, Deniz olur; Berk dördüncüdür.'),
  ('Altı kişi çay içmek için sırayla oturacaktır: Aras birinci, Funda sonuncudur. Emre, Bahar\'dan önce; Bahar, Cem\'den önce; Dila ise Cem\'in hemen önüne oturur. Emre ikinci sıradadır. Dördüncü sırada kim oturur?', 'Dila', ['Aras', 'Bahar', 'Cem'], 'Sıra Aras, Emre, Bahar, Dila, Cem, Funda olur; dördüncü Dila\'dır.'),
  ('1³ + 2³ + 3³ + … + 8³ toplamının, 1 + 2 + … + 8 toplamının karesine eşit olduğu bilinmektedir. Bu toplam kaçtır?', '1296', ['12960', '1332', '1200'], '1 + 2 + … + 8 = 36 ve 36² = 1296.'),
  ('1 − 2 + 3 − 4 + 5 − 6 + … + 99 − 100 işleminin sonucu kaçtır?', '-50', ['50', '-100', '0'], 'Ardışık ikili gruplar (1−2), (3−4), … her biri −1\'dir ve 50 grup vardır: -50.'),
  ('Bir dizinin terimleri 12, 21, 34, 43, 56, … biçiminde ilerlemektedir (sayılar, çift ve tek sıralı terimlerde rakam yer değiştirmesiyle bağlıdır). Dizinin 6. terimi kaçtır?', '65', ['67', '650', '87'], 'Terimler 12–21, 34–43, 56–65 biçiminde çiftler oluşturur; 6. terim 56\'nın rakamlarının yer değiştirmişidir.'),
  ('Bir sayıdan başlanarak şu kurala göre dizi yazılıyor: sayı çiftse yarısı, tekse 3 katının 1 fazlası alınıyor. İlk terim 7 ise dizinin 10. terimi kaçtır?', '20', ['40', '17', '200'], 'Terimler: 7, 22, 11, 34, 17, 52, 26, 13, 40, 20.'),
  ('İlk terimi 1 olan bir dizide terimler sırasıyla 2 ile çarpılıp 3 eklenerek (×2, +3, ×2, +3, …) ilerlemektedir. 8. terim kaçtır?', '58', ['580', '29', '52'], 'Terimler: 1, 2, 5, 10, 13, 26, 29, 58.'),
  ('Her doğal sayının pozitif bölenlerinin sayısını veren bir dizide 1 için 1, 2 için 2, 3 için 2, 4 için 3, 5 için 2, 6 için 4 değerleri yazılıyor. 36 için bu dizideki terim kaçtır?', '9', ['8', '10', '12'], '36 = 2²·3² olduğundan bölen sayısı (2+1)(2+1) = 9.'),
  ('1², 2², 3², … sayılarının 5\'e bölümünden kalanlar sırasıyla 1, 4, 4, 1, 0, 1, 4, 4, 1, 0, … şeklinde tekrar etmektedir. 100². sayının (yani 100 sayısının karesinin) 5\'e bölümünden kalan kaçtır?', '0', ['1', '10', '3'], 'Dizinin devri 5\'tir ve 100 sayısı 5\'in katı olduğundan kalan 0.'),
  ('x, 12, y sayıları bu sırayla geometrik dizi oluşturmaktadır ve x·y çarpımı kaçtır?', '144', ['24', '1440', '36'], 'Ortadaki terimin karesi uçlardaki terimlerin çarpımına eşittir: x·y = 12² = 144.'),
  ('2 ile 98 arasına, sayılar toplam olarak bir aritmetik dizi oluşturacak biçimde 11 sayı yerleştiriliyor. Dizinin ortadaki (7.) terimi kaçtır?', '50', ['48', '500', '49'], 'Ortadaki terim, uçların ortalamasıdır: (2 + 98)/2 = 50.'),
  ('1 ile 1024 arasına, bir geometrik dizi oluşturacak biçimde 9 sayı yerleştirilirse (toplam 11 terim) dizinin ortak çarpanı kaç olur?', '2', ['3', '4', '20'], '1·r^10 = 1024 ⇒ r = 2.'),
  ('Aynı sinyal şifresinde A = .-, E = ., I = .., M = --, N = -., T = - işaretleri kullanılmaktadır. \'.- -. -\' dizisi hangi sözcüğü gösterir?', 'ANT', ['ENT', 'AIM', 'MAN'], 'Dizi sırasıyla A (.-), N (-.) ve T (-) harflerini verir; sözcük ANT\'tır.'),
  ('Beş satır ve beş sütunlu bir harf çizelgesinde satırlar ABCDE, FGHIK, LMNOP, QRSTU, VWXYZ şeklindedir (J harfi kullanılmaz). Bir harf, önce bulunduğu satır sonra sütun numarasıyla (ör. A = 11, G = 22) yazılıyor. Bu şifreyle HOT sözcüğü nasıl yazılır?', '23-34-44', ['32-34-44', '23-43-44', '23-34-45'], 'H = 23, O = 34, T = 44 olduğundan 23-34-44.'),
  ('Beş satır ve beş sütunlu bir harf çizelgesinde satırlar ABCDE, FGHIK, LMNOP, QRSTU, VWXYZ şeklindedir (J harfi yoktur). Bir harf satır ve sütun numarasıyla (A = 11, K = 25) yazılıyor. \'31-15-14\' şifresi hangi sözcüğü verir?', 'LED', ['LEAN', 'LIED', 'FEED'], '31 = L, 15 = E, 14 = D olduğundan sözcük LED.'),
  ('Bir şifrede her harfin yerine, o harfin sözcükte kaç kez geçtiği yazılıyor. Bu şifreyle MERHABA sözcüğü nasıl yazılır?', '1111212', ['1111313', '11112120', '1111211'], 'MERHABA\'da A iki kez geçer; diğer harfler birer kez: M1, E1, R1, H1, A2, B1, A2 ⇒ 1111212.'),
  ('Bir klavyenin üst sırası Q W E R T Y U I O P biçimindedir. Bir şifrede her harf, bu sırada hemen sağındaki harfle değiştiriliyor. Bu şifreyle TIE sözcüğü nasıl yazılır?', 'YOR', ['RUW', 'UPT', 'EIT'], 'T→Y, I→O, E→R olduğundan YOR.'),
  ('Bir kimlik numarasının son hanesi, önceki üç rakamın sırasıyla 1, 2, 3 ile çarpılıp toplanmasından elde edilen sonucun 7\'ye bölümünden kalandır. İlk üç hanesi 5, 3, 4 olan numaranın son hanesi kaçtır?', '2', ['1', '20', '5'], '5·1 + 3·2 + 4·3 = 23; 23\'ün 7\'ye bölümünden kalan 2\'dir.'),
  ('Hep doğru ya da hep yalan söyleyen üç arkadaştan Efe, \'Gül yalancıdır.\' Gül, \'Hakan yalancıdır.\' Hakan ise \'Efe ile Gül aynı türdendir.\' demiştir. Bu üç kişiden kaçı doğru söylemektedir?', '1', ['0', '2', '10'], 'Efe doğruysa Gül yalancı, Hakan doğru olur; ama Hakan\'ın sözü (Efe ile Gül aynı tür) yanlış kalır. Efe yalancıysa Gül doğru, Hakan yalancı olur ve Hakan\'ın sözü gerçekten yanlıştır. Yalnız Gül doğru söyler.'),
  ('Bir odada Kaan, Lale ve Mert vardır; her biri ya hep doğru ya hep yalan söylemektedir. Kaan, \'Lale yalancıdır.\' Lale, \'Mert yalancıdır.\' Mert ise \'Kaan ve Lale yalancıdır.\' demiştir. Kaç kişi doğru söylemektedir?', '1', ['10', '2', '3'], 'Kaan doğruysa Lale yalancı, Mert doğru; ama Mert\'in sözü (Kaan yalancı) çelişir. Kaan yalancı ⇒ Lale doğru ⇒ Mert yalancı; Mert\'in sözü yanlıştır ve tutarlıdır. Yalnız Lale doğru söyler.'),
  ('Bir bardağı kıran kişi Ayla, Barış, Can ve Dilek\'ten biridir. Ayla, \'Barış kırdı.\' Barış, \'Can kırdı.\' Can, \'Barış yalan söylüyor.\' Dilek, \'Ben kırmadım.\' demiştir. Dört sözden yalnız biri doğru olduğuna göre bardağı kim kırmıştır?', 'Dilek', ['Ayla', 'Barış', 'Can'], 'Her adayı sınayınca yalnız Dilek kırdığında tam bir söz doğru olur.'),
  ('Bir camı kıran kişi Emre, Fidan, Gökhan ve Hale\'den biridir. Emre, \'Fidan kırdı.\' Fidan, \'Gökhan kırdı.\' Gökhan, \'Ben kırmadım.\' Hale, \'Fidan doğru söylemiyor.\' demiştir. Dört sözden tam üçü doğru olduğuna göre camı kim kırmıştır?', 'Fidan', ['Emre', 'Gökhan', 'Hale'], 'Her adayı sınayınca yalnız Emre kırdığında tam üç söz doğru olur.'),
  ('Bir bisikleti çalan kişi Irmak, Kemal, Lale ve Melih\'ten biridir. Irmak, \'Kemal çaldı.\' Kemal, \'Lale çaldı.\' Lale, \'Kemal doğru söylemiyor.\' Melih, \'Ben çalmadım.\' demiştir. Yalnız biri doğru söylediğine göre bisikleti kim çalmıştır?', 'Melih', ['Irmak', 'Kemal', 'Lale'], 'Her adayı sınayınca yalnız Melih çaldığında tam bir söz doğru olur.'),
  ('1\'den 9\'a kadar sayıların birer kez kullanıldığı 3×3\'lük bir sihirli karede (her satır, sütun ve köşegen toplamı eşittir) orta karedeki sayı kaçtır?', '5', ['3', '50', '6'], 'Satır toplamı 15\'tir; ortadaki sayı 15/3 = 5\'tir.'),
  ('1\'den 16\'ya kadar sayıların birer kez kullanıldığı 4×4\'lük bir sihirli karede her satırın toplamı kaçtır?', '34', ['30', '32', '340'], 'Toplam 136; 4 satır için her satır 136/4 = 34.'),
  ('2\'den 10\'a kadar ardışık dokuz sayı bir 3×3 sihirli kareye yerleştirilmiştir. Her satırın toplamı kaçtır?', '18', ['180', '20', '27'], 'Toplam 54; 3 satır için 54/3 = 18.'),
  ('Bir 3×3 sihirli karede ortadaki sayı 9\'dur. Her satırın toplamı kaçtır?', '27', ['18', '270', '30'], 'Satır toplamı ortadaki sayının 3 katıdır: 27.'),
  ('Bir 3×3 sihirli karede sol üst köşede 4, sağ alt köşede 12 sayısı yazılıdır ve ortadaki sayı 8\'dir. Sağ üst köşede 6 yazıyorsa sol alt köşedeki sayı kaçtır?', '10', ['8', '12', '100'], 'Köşegen toplamı 4 + 8 + 12 = 24\'tür; diğer köşegende 6 + 8 + x = 24 ⇒ x = 10.'),
  ('1\'den 12\'ye kadar çarpım çizelgesinde (12×12\'lik, her kutuda satır ve sütun numarasının çarpımı bulunur) 24 sayısı kaç kutuda görünür?', '6', ['60', '5', '8'], 'Çarpanlar: (2,12), (3,8), (4,6) ve ters sıralamaları (6 kutu). Sayı 6 kutuda bulunur.'),
  ('1\'den 10\'a kadar çarpım çizelgesinde (10×10) 36 sayısı kaç kutuda yer alır?', '3', ['2', '30', '5'], 'Çarpanlar (4,9), (9,4), (6,6) olmak üzere 3 kutudur.'),
  ('Bir çizelgenin satır toplamları 18, 27 ve ? ; sütun toplamları ise 20, 25 ve 30\'dur. Soru işareti yerine hangi sayı gelmelidir?', '30', ['28', '32', '300'], 'Genel toplam 75\'tir; ? = 75 − 45 = 30.'),
  ('Sayılar soldan sağa ve yukarıdan aşağıya doğru 1\'den başlayarak 6 sütunlu bir çizelgeye sırayla yazılıyor. 4. satırın 3. sütunundaki sayı kaçtır?', '21', ['210', '24', '27'], 'Bu kutudan önce 3 tam satır (18 sayı) vardır; sayı 18 + 3 = 21.'),
  ('Sayılar 1\'den başlayarak 7 sütunlu bir çizelgeye soldan sağa, yukarıdan aşağıya sırayla yazılıyor. 50 sayısı hangi sütundadır?', '1', ['5', '10', '7'], '50 = 7·7 + 1 olduğundan sayı 8. satırın 1. sütunundadır.'),
  ('Bir mimar, her kat için gereken kolon sayısını 3, 3, 5, 9, … biçiminde planlamış ve sayıları n² − 3n + 5 kuralıyla bulmuştur. 11. kat için kaç kolon gerekir?', '93', ['75', '113', '111'], 'Genel terim n² − 3n + 5\'tir. Buna göre 11. terim 93 olur.'),
  ('Bir oyun kartı koleksiyonunda seri numaraları 2, 10, 24, 44, … şeklinde ilerliyor ve 3n² − n kuralına uyuyor. 9. seri numarası kaçtır?', '234', ['184', '290', '284'], 'Genel terim 3n² − n\'dir. Buna göre 9. terim 234 olur.'),
  ('Bir fabrikanın üretim hattında parça numaraları 2, 16, 54, 128, … şeklinde 2n³ kuralıyla artmaktadır. 7. numara kaçtır?', '686', ['432', '1024', '940'], 'Genel terim 2n³\'tür. Buna göre 7. terim 686 olur.'),
  ('Bir ağaç türünün yıllara göre yaprak sayıları 1, 13, 61, 253, … şeklinde 4^n − 3 kuralıyla artıyor. 6. yılın yaprak sayısı kaçtır?', '4093', ['1021', '16381', '7165'], 'Genel terim 4^n − 3\'tür. Buna göre 6. terim 4093 olur.'),
  ('Bir dizinin genel terimi ⌊n²/2⌋\'dir (n²/2\'nin tam kısmı). Dizi 0, 2, 4, 8, 12, 18, … biçimindedir. 15. terim kaçtır?', '112', ['98', '128', '126'], '15² = 225, 225/2 = 112,5 ⇒ tam kısım 112. Buna göre 15. terim 112 olur.'),
  ('Bir sayma dizisinde terimler 6, 27, 128, … şeklinde 5^n + n kuralıyla bulunmaktadır. 5. terim kaçtır?', '3130', ['629', '15631', '5631'], 'Genel terim 5^n + n\'dir. Buna göre 5. terim 3130 olur.'),
  ('Bir bakteri deneyinde her saat sayılar 1, 7, 19, 43, … şeklinde 3·2^n − 5 kuralıyla artmaktadır. 8. saat sayısı kaçtır?', '763', ['379', '1531', '1147'], 'Genel terim 3·2^n − 5\'tir. Buna göre 8. terim 763 olur.'),
  ('Bir sınıfın sıralarındaki öğrenci sayıları 43, 47, 53, 61, … olarak n² + n + 41 kuralıyla belirleniyor (bu kuralın ilk terimleri asal sayılardır). 10. terim kaçtır?', '151', ['131', '173', '171'], 'Genel terim n² + n + 41\'dir. Buna göre 10. terim 151 olur.'),
  ('3, 14, 39, … dizisinde her terim n + n² + n³ toplamıdır. 6. terim kaçtır?', '258', ['155', '399', '361'], 'Genel terim n + n² + n³\'tür. Buna göre 6. terim 258 olur.'),
  ('Rozet numaraları 8, 35, 80, … biçiminde, genel terimi 9n² − 1 olan bir dizi oluşturuyor. 8. rozetin numarası kaçtır?', '575', ['440', '728', '710'], 'Genel terim 9n² − 1\'dir. Buna göre 8. terim 575 olur.'),
  ('12, 20, 30, 42, … dizisinin n. terimi (n + 2)(n + 3)\'tür. 13. terim kaçtır?', '240', ['210', '272', '270'], 'Genel terim (n + 2)(n + 3)\'tür. Buna göre 13. terim 240 olur.'),
  ('Bir sergi salonunda ziyaretçi sayısı hafta hafta 3, 6, 10, 15, 21, … şeklinde ilerliyor; terimler C(n + 2, 2) kuralıyla veriliyor. 10. haftadaki ziyaretçi sayısı kaçtır?', '66', ['55', '78', '77'], 'C(n + 2, 2) = (n + 2)(n + 1)/2\'dir; 12·11/2 = 66. Buna göre 10. terim 66 olur.'),
  ('5, 14, 27, 44, … dizisinde terimler 2n² + 3n kuralıyla elde edilmiştir. 9. terim kaçtır?', '189', ['152', '230', '226'], 'Genel terim 2n² + 3n\'dir. Buna göre 9. terim 189 olur.'),
  ('Bir kuyumcunun aylık ürettiği yüzük sayıları -1, 4, 21, 56, … biçiminde, n³ − 2n kuralına göre değişiyor. 7. ayda üretilen yüzük sayısı kaçtır?', '329', ['204', '496', '454'], 'Genel terim n³ − 2n\'dir. Buna göre 7. terim 329 olur.'),
  ('Bir satranç topluluğunda üye sayıları yıllara göre 1, 5, 19, 65, … biçiminde 3^n − 2^n kuralıyla artmaktadır. 6. yılda üye sayısı kaçtır?', '665', ['211', '2059', '1119'], 'Genel terim 3^n − 2^n\'dir. Buna göre 6. terim 665 olur.'),
  ('Bir dizinin terimleri 5, 13, 35, … şeklinde 2^n + 3^n kuralıyla bulunmaktadır. 6. terim kaçtır?', '793', ['275', '2315', '1311'], 'Genel terim 2^n + 3^n\'dir. Buna göre 6. terim 793 olur.'),
  ('Bir arıcının kovanlarından toplanan bal miktarları (kg) 12, 20, 30, 42, … biçiminde n² + 5n + 6 kuralıyla artıyor. 10. dönemdeki miktar kaç kg\'dır?', '156', ['132', '182', '180'], 'Genel terim n² + 5n + 6 = (n + 2)(n + 3)\'tür. Buna göre 10. terim 156 olur.'),
  ('Merkezli altıgen sayılar 7, 19, 37, 61, … biçiminde ilerler ve genel terimleri 3n² + 3n + 1\'dir. 7. terim kaçtır?', '169', ['127', '217', '211'], 'Genel terim 3n² + 3n + 1\'dir. Buna göre 7. terim 169 olur.'),
  ('2, 12, 36, 80, … dizisinde her terim n³ + n² olarak bulunur. 8. terim kaçtır?', '576', ['392', '810', '760'], 'Genel terim n³ + n²\'dir. Buna göre 8. terim 576 olur.'),
  ('2 → 6, 3 → 12, 4 → 20 eşleşmeleri veriliyor. Aynı kurala göre 7 hangi sayıya dönüşür?', '56', ['49', '42', '63'], 'Kural n(n + 1)\'dir: 7·8 = 56.'),
  ('Bir makine 3\'ü 10\'a, 4\'ü 17\'ye, 5\'i 26\'ya çeviriyor. Aynı makine 8\'i hangi sayıya çevirir?', '65', ['64', '57', '66'], 'Kural n² + 1\'dir: 8² + 1 = 65.'),
  ('Bir makinede 3 → 6, 4 → 24, 5 → 120 eşleşmeleri vardır. Aynı kuralla 6 sayısı hangi sayıya karşılık gelir?', '720', ['360', '600', '144'], 'Kural n! dir: 6! = 720.'),
  ('5 → 12, 7 → 16, 10 → 22 eşleşmelerine göre aynı kuralla 15 sayısı hangi sayıya karşılık gelir?', '32', ['30', '34', '31'], 'Kural 2n + 2\'dir: 2·15 + 2 = 32.'),
  ('(2, 3) çifti 13\'e, (3, 4) çifti 25\'e, (1, 5) çifti 26\'ya karşılık gelmektedir. (4, 5) çifti hangi sayıya karşılık gelir?', '41', ['40', '45', '36'], 'Kural a² + b²\'dir: 16 + 25 = 41.'),
  ('AB sözcüğü ZY\'ye, CD sözcüğü XW\'ye dönüşüyor (İngiliz alfabesi, her harf karşıt konumundaki harfle değişiyor). Aynı kurala göre EF nasıl yazılır?', 'VU', ['UV', 'WV', 'XW'], 'E↔V, F↔U olduğundan sonuç VU\'dur.'),
  ('8, 27, 64, 100, 125 sayılarından biri, diğerlerinin ortak özelliğini taşımamaktadır. Bu sayı hangisidir?', '100', ['8', '27', '64'], 'Diğerleri tam küptür; 100 tam küp değildir.'),
  ('1, 3, 6, 10, 14, 15 listesinde üçgen sayı olmayan terim hangisidir?', '14', ['3', '6', '10'], 'Üçgen sayılar 1, 3, 6, 10, 15, 21, … biçimindedir; 14 üçgen sayı değildir.'),
  ('21, 35, 49, 56, 64 sayılarından hangisi, diğer dördünün ortak özelliğini taşımamaktadır?', '64', ['21', '35', '49'], 'Diğerleri 7\'nin katıdır; 64, 7\'ye bölünmez.'),
  ('3, 6, 12, 24, 48, 94 sayı listesinde bir terim diğerlerinin izlediği kurala uymuyor. Bu terim hangisidir?', '94', ['48', '24', '12'], 'Her terim bir öncekinin iki katıdır; 48\'in iki katı 96\'dır, 94 değil.'),
  ('5, 10, 20, 40, 75, 80 listesinde ardışık terimlerin oranı sabit olmalıdır. Bu kurala uymayan terim hangisidir?', '75', ['10', '20', '40'], 'Kurala göre terimler 5, 10, 20, 40, 80 olmalıdır; 75 uymaz.'),
  ('2, 6, 12, 20, 30, 42, 50 dizisinde ardışık iki doğal sayının çarpımı olmayan terim hangisidir?', '50', ['2', '12', '30'], 'Terimler n(n+1) biçimindedir; 50 yerine 56 olmalıdır.'),
  ('Kibrit çöpleriyle 2 satırlı dikdörtgen bir kare ızgarası kuruluyor: tek sütunlu (1×2) ızgara için 7, iki sütunlu için 12, üç sütunlu için 17 çöp gerekiyor. 12 sütunlu 2×12\'lik ızgara için kaç çöp gerekir?', '62', ['60', '64', '72'], 'Çöp sayısı 5n + 2 olduğundan 5·12 + 2 = 62.'),
  ('3 satırlı kare ızgaralar kibrit çöpüyle kuruluyor: 1 sütun için 10, 2 sütun için 17 çöp gerekiyor. 10 sütunlu ızgara için kaç çöp gerekir?', '73', ['70', '77', '80'], 'Çöp sayısı 7n + 3\'tür: 73.'),
  ('6×6×6\'lık bir küp birim küplerden oluşuyor ve tüm yüzeyi boyanıyor. Hiçbir yüzü boyanmamış birim küp sayısı kaçtır?', '64', ['36', '48', '100'], 'İçteki 4×4×4\'lük küp boyanmamıştır: 64.'),
  ('5×5×5\'lik bir küpün yüzeyi boyanıp birim küplere ayrılıyor. Yalnız bir yüzü boyalı olan birim küp sayısı kaçtır?', '54', ['27', '36', '48'], 'Her yüzde iç kısımdaki 3×3 = 9 küp tek yüzlü boyalıdır; 6·9 = 54.'),
  ('Yan yana dizilmiş 20 küpten oluşan bir küp zincirinin (her küp komşusuyla bir yüzünden birleşmiştir) dış yüzey alanı kaç birim karedir?', '82', ['80', '84', '120'], 'Yüzey alanı 4n + 2\'dir: 4·20 + 2 = 82.'),
  ('Bir kenarı 1 birim olan siyah eşkenar üçgenden başlanıp her adımda her siyah üçgenin içinden ortadaki üçgen çıkarılırsa (Sierpinski üçgeni) 6. adımda kaç siyah üçgen kalır?', '729', ['243', '216', '364'], 'Her adımda siyah üçgen sayısı 3 katına çıkar: 3⁶ = 729.'),
  ('Bir doğru parçasının her kenarı üçe bölünüp ortadaki parça yerine iki kenarlı bir tepe konuyor; böylece her adımda kenar sayısı 4 katına çıkıyor. Başlangıçta 1 kenar varken 5 adım sonra kaç kenar olur?', '1024', ['256', '625', '1000'], 'Kenar sayısı 4^n olduğundan 4⁵ = 1024.'),
  ('0,1 mm kalınlığındaki bir kâğıt 10 kez ortadan ikiye katlanıyor. Katlanmış kâğıdın kalınlığı kaç mm\'dir?', '102,4', ['1,0', '10,24', '51,2'], 'Kalınlık 2^10 = 1024 katına çıkar: 0,1·1024 = 102,4 mm.'),
  ('Ocak ayının 1\'i cuma ise (Ocak 31 gün çeker) şubat ayının 1\'i haftanın hangi gününe denk gelir?', 'Pazartesi', ['Salı', 'Pazar', 'Çarşamba'], '31 = 4·7 + 3; cumadan üç gün ilerlenir: Pazartesi.'),
  ('2023 yılının 1 Ocak günü pazardır. Artık yıl olmayan 2023\'ün ardından gelen 2024 yılının 1 Ocak günü haftanın hangi günüdür?', 'Pazartesi', ['Salı', 'Pazar', 'Çarşamba'], '365 = 52·7 + 1; pazardan bir gün ilerlenir: Pazartesi.'),
  ('Bir sınavdan tam 45 gün önce bir perşembe günü sınav takvimi açıklanmıştır. Sınav günü haftanın hangi günüdür?', 'Pazar', ['Pazartesi', 'Cumartesi', 'Salı'], '45 = 6·7 + 3; perşembeden üç gün ilerlenir: Pazar.'),
  ('Saat 12 saatlik analog bir saatte 4\'ü gösteriyor. Tam 100 saat sonra saat kaçı gösterir?', '8', ['6', '9', '10'], '100 = 8·12 + 4; 4 + 4 = 8.'),
  ('24 saatlik dijital bir saat 22.00\'ı gösteriyor. 50 saat sonra bu saat kaçı gösterir?', '00.00', ['02.00', '22.00', '20.00'], '50 = 2·24 + 2; 22 + 2 = 24 ⇒ 00.00.'),
  ('Bir nöbetçi eczane çizelgesinde 6 eczane sırayla birer gün nöbet tutar ve sıra başa döner. 1. gün nöbetçi A eczanesi ise 100. gün hangi sıradaki eczane nöbettedir? (A=1, B=2, … F=6)', '4', ['3', '5', '2'], '100 = 16·6 + 4 olduğundan 4. eczane (D) nöbetçidir.'),
  ('Bir şifrede her harf, alfabedeki sıra numarasının 27\'den farkıyla yazılıyor (A yerine 26, B yerine 25, …; İngiliz alfabesi). Bu şifreyle CAT sözcüğü nasıl yazılır?', '24-26-7', ['3-1-20', '24-26-8', '25-26-7'], 'C=3→24, A=1→26, T=20→7 ⇒ 24-26-7.'),
  ('Bir gizli yazışmada cümledeki her sözcüğün son harfi alınıyor. \'Ali kapı bulut deniz\' sözcüklerinden elde edilen şifreli sözcük nedir?', 'İITZ', ['AKBD', 'IITZ', 'TZİI'], 'Son harfler: i, ı, t, z ⇒ İITZ.'),
  ('Bir şifrede her sözcüğün harfleri kendi içinde alfabetik sıraya (A\'dan Z\'ye) dizilip tersten yazılıyor. Bu yöntemle DENİZ sözcüğü nasıl yazılır? (Türk alfabesine göre sıralama: D, E, İ, N, Z.)', 'ZNİED', ['DEİNZ', 'ZİNED', 'ZNEİD'], 'Alfabetik sıra D, E, İ, N, Z; tersi Z, N, İ, E, D olur.'),
  ('Bir şifreleme anahtarı 2-0-1 rakamlarıdır: sözcüğün birinci harfi 2, ikinci harfi 0, üçüncü harfi 1 ileri kaydırılır; anahtar yinelenerek sürer (İngiliz alfabesi). Bu anahtarla HAPPY sözcüğü nasıl yazılır?', 'JAQRY', ['IARQY', 'JBPRZ', 'IBQQZ'], 'H+2=J, A+0=A, P+1=Q, P+2=R, Y+0=Y ⇒ JAQRY.'),
  ('Bir şifrede harfler İngiliz alfabesinde sırasıyla 1, 2, 3 ve yeniden 1, 2, 3 … ileri kaydırılıyor. Bu şifreyle ZEBRA sözcüğü nasıl yazılır? (Z\'den sonra A gelir.)', 'AGESC', ['CGCUC', 'AFCSB', 'BFETB'], 'Z+1=A, E+2=G, B+3=E, R+1=S, A+2=C ⇒ AGESC.'),
  ('Bir pencereyi açık bırakan kişi Nazlı, Onur, Pelin ve Rüzgâr\'dan biridir. Nazlı, \'Onur bıraktı.\' Onur, \'Pelin bıraktı.\' Pelin, \'Ben bırakmadım.\' Rüzgâr, \'Onur yalan söylüyor.\' demiştir. Yalnız biri yalan söylediğine göre pencereyi kim açık bırakmıştır?', 'Onur', ['Nazlı', 'Pelin', 'Rüzgâr'], 'Her adayı sınayınca yalnız bir aday tam üç doğru söz verir.'),
  ('Bir kasanın şifresi rakamları birbirinden farklı üç basamaklı bir sayıdır. Deneme sonuçları: 693 için 1 rakamı var ama yanlış yerde; 047 için 1 rakamı doğru yerde, 1 rakamı var ama yanlış yerde; 549 için 2 rakamı doğru yerde; 614 için 1 rakamı var ama yanlış yerde. Üç rakamın toplamı kaçtır?', '20', ['21', '19', '22'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 749 olur.'),
  ('Bir bavul kilidi rakamları farklı üç haneli bir kodla açılıyor. Denemelerde şunlar gözlenmiştir: 765 için 1 rakamı doğru yerde; 629 için 1 rakamı var ama yanlış yerde; 713 için 1 rakamı var ama yanlış yerde; 382 için 1 rakamı doğru yerde, 1 rakamı var ama yanlış yerde. Şifrenin ilk rakamı kaçtır?', '3', ['4', '2', '5'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 368 olur.'),
  ('Bir telefon ekranının kilidi, rakamları farklı üç rakamlı bir koddur. Bir kullanıcının bulduğu ipuçları şöyledir: 327 için 1 rakamı var ama yanlış yerde; 903 için 1 rakamı doğru yerde; 215 için 2 rakamı doğru yerde; 739 için hiçbir rakamı sayıda yok. Şifrenin son rakamı kaçtır?', '5', ['6', '4', '7'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 205 olur.'),
  ('Bir dolap kilidinin açılış kodu, hiçbir rakamı tekrar etmeyen üç basamaklı bir sayıdır. Denemeler: 924 için 1 rakamı doğru yerde; 748 için 2 rakamı var ama yanlış yerde; 047 için 2 rakamı var ama yanlış yerde; 654 için 1 rakamı doğru yerde, 1 rakamı var ama yanlış yerde. Üç rakamın toplamı kaçtır?', '16', ['17', '15', '18'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 574 olur.'),
  ('Bir müzedeki vitrin kilidi, rakamları farklı üç haneli bir şifreyle açılıyor. Güvenlik görevlisinin tuttuğu kayıtlar: 152 için 1 rakamı doğru yerde; 824 için 3 rakamı var ama yanlış yerde; 810 için 1 rakamı var ama yanlış yerde; 907 için hiçbir rakamı sayıda yok. Şifrenin ilk rakamı kaçtır?', '4', ['5', '3', '6'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 482 olur.'),
  ('Bir bisiklet zincirinin şifresi hiçbir rakamı tekrarlamayan üç basamaklı bir sayıdır. Yapılan denemelerin sonuçları: 357 için 2 rakamı doğru yerde; 718 için 1 rakamı doğru yerde, 1 rakamı var ama yanlış yerde; 297 için 1 rakamı doğru yerde; 572 için 1 rakamı var ama yanlış yerde. Üç rakamın toplamı kaçtır?', '11', ['12', '10', '13'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 317 olur.'),
  ('Bir kütüphane dolabının kodu, rakamları farklı üç haneli bir sayıdır. Kütüphanecinin notları: 196 için 1 rakamı doğru yerde, 1 rakamı var ama yanlış yerde; 268 için 2 rakamı var ama yanlış yerde; 954 için 1 rakamı doğru yerde; 018 için hiçbir rakamı sayıda yok. Şifrenin son rakamı kaçtır?', '6', ['7', '5', '8'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 926 olur.'),
  ('Bir kumbaranın üç haneli, rakamları farklı bir şifresi vardır. Kardeşinin yaptığı denemeler: 639 için 1 rakamı doğru yerde, 2 rakamı var ama yanlış yerde; 795 için 1 rakamı doğru yerde; 654 için 1 rakamı doğru yerde; 638 için 1 rakamı doğru yerde, 1 rakamı var ama yanlış yerde. Üç rakamın toplamı kaçtır?', '18', ['19', '17', '20'], 'Bütün ipuçlarını birlikte sağlayan tek üç basamaklı (rakamları farklı) şifre 693 olur.'),
  ('Aşağıdakilerden hangisi ortak çarpanı 1/3 olan geometrik dizidir?', '81, 27, 9, 3', ['81, 78, 75, 72', '9, 3, 1, 0', '1, 3, 9, 27'], 'Her terim öncekinin 1/3\'üdür.'),
  ('Aşağıdaki dizilerin hangisinde ardışık terimlerin farkları sabit olmamakla birlikte farkların farkı sabittir?', '1, 4, 9, 16, 25', ['5, 9, 13, 17, 21', '2, 6, 18, 54, 162', '7, 7, 7, 7, 7'], 'Farklar 3, 5, 7, 9 şeklinde ikişer artar; farkların farkı sabittir (2).'),
  ('Terimleri 2, 6, 18, 54, … olan geometrik dizide kaçıncı terim 1000\'i ilk kez aşar?', '7', ['5', '8', '9'], '2·3^(n−1) > 1000 koşulunda n = 7: 2·729 = 1458.'),
  ('İlk n çift doğal sayının (2, 4, 6, …) toplamı n(n + 1)\'dir. Bu toplam kaç terimde ilk kez 500\'ü aşar?', '22', ['21', '23', '24'], 'n(n + 1) > 500 için n = 22: 22·23 = 506.'),
  ('7, 11, 15, 19, … aritmetik dizisinde kaç terim iki basamaklı bir sayıdır?', '23', ['22', '24', '20'], 'Terimler 4n + 3 biçimindedir; iki basamaklı olanlar 11\'den 99\'a kadardır (n = 2, …, 24): 23 terim.'),
  ('Bir aritmetik dizide 5. terimle 9. terimin toplamı 40\'tır. Bu dizinin 7. terimi kaçtır?', '20', ['16', '18', '22'], 'a5 + a9 = 2a7 olduğundan a7 = 20.'),
  ('Bir kolonideki birey sayıları her turda aynı katsayıyla çoğalıyor: ilk turda 2, üçüncü turda 18 birey vardır (katsayı pozitiftir). Dördüncü turdaki birey sayısı kaçtır?', '54', ['36', '27', '162'], 'r² = 9 ⇒ r = 3; a4 = 18·3 = 54.'),
  ('Toplamları 75 olan ardışık beş tek sayıdan en küçüğü kaçtır?', '11', ['9', '13', '15'], 'Ortadaki sayı 75/5 = 15; en küçük 15 − 4 = 11.'),
  ('1\'den başlayarak ardışık doğal sayılar toplanıyor. Toplam 210\'a eşit olduğunda kaç sayı toplanmıştır?', '20', ['19', '21', '18'], 'n(n + 1)/2 = 210 ⇒ n = 20.'),
  ('Bir sayı oyununda birbirini izleyen üç çift doğal sayı çarpılınca 480 elde ediliyor. Oyuncunun bulması gereken, bu üç sayının büyüğü hangisidir?', '10', ['8', '12', '6'], '6·8·10 = 480 olduğundan en büyük sayı 10\'dur.'),
  ('Türk alfabesindeki 29 harf sırayla numaralandırılıyor (A=1, B=2, C=3, Ç=4, …). KEDİ sözcüğünün harf değerleri toplamı kaçtır?', '37', ['35', '36', '38'], 'K=14, E=6, D=5, İ=12; toplam 37.'),
  ('Bir ay 31 gün sürüyor ve ayın ilk günü salıdır. Bu ayın dördüncü cuma günü ayın kaçıncı günüdür?', '25', ['22', '24', '26'], 'İlk cuma 4. gündür; dördüncü cuma 4 + 21 = 25. gündür.'),
  ('Bir ayın 12\'si pazar ise aynı ayın 30\'u haftanın hangi günüdür?', 'Perşembe', ['Pazartesi', 'Salı', 'Cuma'], '18 = 2·7 + 4; pazardan dört gün ilerlenir: Perşembe.'),
  ('Bir fabrikanın ilk gün ürettiği ürün sayısı 100\'dür; her gün bir önceki günün %10 fazlası üretiliyor. 3. günün üretimi kaç adettir?', '121', ['120', '110', '133'], '100·1,1² = 121 adet.'),
  ('Genel terimi 3n + 4 olan dizide ilk kez 100\'ü aşan terim kaçtır?', '103', ['100', '101', '104'], '3n + 4 > 100 ⇒ n ≥ 33; 33. terim 103\'tür.'),
  ('Genel terimi 2^n olan dizinin ilk kez 5000\'i aşan terimi kaçtır?', '8192', ['4096', '5120', '6000'], '2¹² = 4096 < 5000 < 2¹³ = 8192.'),
];
